		FormSecurityBuilder GetFormSecurityBuilderForShipmentInterface(SecurityCheckpoint root, string formToken, bool hasViewSecurityPoint, bool hasEditSecurityPoint)
		{
			return new FormSecurityBuilder(root, SecurityInstance, hasViewSecurityPoint, hasEditSecurityPoint)
			.Form(formToken)
				.Tab("ShipmentDetailsTabPage", ResString.GetMultilingualString("c017a441-af64-47b1-9096-65fabc759f3e", "Basic Registration"))
