		protected virtual bool ClientHookIsLoaded
		{
			get { return ClientHookLoader.Instance.ClientHook != null; }
		}

		protected virtual void AddClientSpecificSecurityCheckpoints()
		{
			ClientHook clientHook = ClientHookLoader.Instance.ClientHook;
			if (ClientHookIsLoaded && clientHook != null)
			{
				clientHook.AddClientSpecificSecurityCheckpointsToSecurityInstance(this);
				var defaultModel = GetJobInvoicingPlugInModel();

				var clientSpecificJobInvoicingCheckpoints = clientHook.GetClientSpecificJobInvoicingCheckpoints(this);
				if (clientSpecificJobInvoicingCheckpoints != null)
				{
					foreach (SecurityCheckpoint checkpoint in clientSpecificJobInvoicingCheckpoints)
					{
						AddJobInvoicingPlugIn(checkpoint, defaultModel);
					}
				}
			}
		}

