		ISecurityCheckpoint GetLazyCheckpoint(CheckpointLookupKey key)
		{
			return key.Code != null ? (SecurityCheckpoint)typeof(SecurityCore).GetProperty(key.Code)?.GetValue(this) : null;
		}

		void InitLazyCheckpoints()
		{
			var propertyInfos = typeof(SecurityCore).GetProperties();
			foreach (var propertyInfo in propertyInfos)
			{
				if (typeof(SecurityCheckpoint).IsAssignableFrom(propertyInfo.PropertyType))
				{
					_ = (SecurityCheckpoint)propertyInfo.GetValue(this);
				}
			}
		}

