		#region Auto-generated checkpoints
		[System.Diagnostics.CodeAnalysis.SuppressMessage("CargoWiseOne", "CW1161:ResGetStringAnalyzer", Justification = "May be an identifier or GUID.")]
		const string autoGeneratedDisplayText = "autogenerateddisplaytext";

		Dictionary<string, PropertyInfo> AutoGeneratedCheckpointProperties
		{
			get
			{
				return autoGeneratedCheckpointProperties ?? (autoGeneratedCheckpointProperties = BuildAutoGeneratedProperties());
			}
		}
		Dictionary<string, PropertyInfo> autoGeneratedCheckpointProperties;

		Dictionary<string, PropertyInfo> BuildAutoGeneratedProperties()
		{
			Dictionary<string, PropertyInfo> propertyCollection = new Dictionary<string, PropertyInfo>();
			PropertyInfo[] properties = typeof(SecurityCore).GetProperties();
			if (properties != null)
			{
				properties = properties.Where(property => property.Name.IndexOf(autoGeneratedDisplayText, StringComparison.OrdinalIgnoreCase) >= 0).ToArray();
				foreach (PropertyInfo property in properties)
				{
					string propertyName = property.Name.Substring(0, property.Name.Length - autoGeneratedDisplayText.Length);
					propertyCollection.Add(propertyName, property);
				}
			}

			return propertyCollection;
		}

		public bool TryGetAutoGeneratedCheckpoint(CheckpointLookupKey lookupKey, out ISecurityCheckpoint checkPoint)
		{
			var property = AutoGeneratedCheckpointProperties.FirstOrDefault(p => lookupKey.Code.IndexOf(p.Key) >= 0);
			if (property.Value != null)
			{
				string displayText = property.Value.GetValue(this, null) as string;
				checkPoint = new SecurityCheckpointNonOperationalAllowed(lookupKey.Code, (NoResString)displayText, Staff, SecurityInstance);
				return true;
			}

			checkPoint = null;
			return false;
		}

