		public void SetJobInvoicingCheckPoints(IZSecurity securityInstance)
		{
			securityInstance.SetJobInvoicingPluginBuilder(MakeJobInvoicingPluginBuilder);
			var defaultModel = GetJobInvoicingPlugInModel();
			AddJobInvoicingPlugIn(MaintainShipmentJobInvoicing, GetJobInvoicingPlugInModel(true, true));
			AddJobInvoicingPlugIn(CustomsDeclarationJobInvoicing, GetJobInvoicingPlugInModel(true));
			AddJobInvoicingPlugIn(JobMAWBJobInvoicing, defaultModel);
			AddJobInvoicingPlugIn(TransportJobInvoicing, GetJobInvoicingPlugInModel(true));
			AddJobInvoicingPlugIn(DtbBookingJobInvoicing, GetJobInvoicingPlugInModel(true));

			AddJobInvoicingPlugIn(DtbConsignmentJobInvoicing, GetJobInvoicingPlugInModel(true));
			AddJobInvoicingPlugIn(DtbConsignmentRunSheetJobInvoicing, GetJobInvoicingPlugInModel(true));

			AddJobInvoicingPlugIn(CFSLoadListJobInvoicing, GetJobInvoicingPlugInModel(true));
			AddJobInvoicingPlugIn(CFSShipmentJobInvoicing, GetJobInvoicingPlugInModel(true));
			AddJobInvoicingPlugIn(CFSGatePassJobInvoicing, defaultModel);

			AddJobInvoicingPlugIn(WhsDocketJobInvoicing, defaultModel);
			AddJobInvoicingPlugIn(WhsReceiveJobInvoicing, defaultModel);
			AddJobInvoicingPlugIn(WhsOrderJobInvoicing, defaultModel);
			AddJobInvoicingPlugIn(WhsInvoicingJobInvoicing, defaultModel);
			AddJobInvoicingPlugIn(WhsStocktakeJobInvoicing, defaultModel);
			AddJobInvoicingPlugIn(WhsWorkOrderJobInvoicing, defaultModel);

			AddJobInvoicingPlugIn(ACAMasterImportJobInvoicing, defaultModel);
			AddJobInvoicingPlugIn(ACAOutturnBillsJobInvoicing, defaultModel);
			AddJobInvoicingPlugIn(AUCustomsAirCTOImportJobInvoicing, defaultModel);
			AddJobInvoicingPlugIn(AUCustomsAirCTOExportJobInvoicing, defaultModel);

			AddJobInvoicingPlugIn(AgencyBookingJobInvoicing, GetJobInvoicingPlugInModel(true));
			AddJobInvoicingPlugIn(AgencyBillOfLadingJobInvoicing, GetJobInvoicingPlugInModel(true, false, true));
			AddJobInvoicingPlugIn(AgencyContainerDetentionJobInvoicing, defaultModel);
			AddJobInvoicingPlugIn(AgencyVoyageAccountJobInvoicing, defaultModel);
			AddJobInvoicingPlugIn(AgencySundryChargesJobInvoicing, defaultModel);

			AddJobInvoicingPlugIn(ImporterSecurityFilingJobInvoicing, defaultModel);
			AddJobInvoicingPlugIn(QuickBookingJobInvoicing, GetJobInvoicingPlugInModel(true));
			AddJobInvoicingPlugIn(OneOffQuoteJobInvoicing, defaultModel);
			AddJobInvoicingPlugIn(USeManifestJobInvoicing, defaultModel);
			AddJobInvoicingPlugIn(ConsolCAeManifestInvoicing, defaultModel);
			AddJobInvoicingPlugIn(WorkItemJobInvoicing, defaultModel);

			AddJobInvoicingPlugIn(WhsItemReceiveConsignmentJobInvoicing, defaultModel);
			AddJobInvoicingPlugIn(WhsItemReceiveTransportationUnitJobInvoicing, defaultModel);
			AddJobInvoicingPlugIn(WhsItemDispatchConsignmentJobInvoicing, defaultModel);
			AddJobInvoicingPlugIn(WhsItemDispatchTransportationUnitJobInvoicing, defaultModel);

			AddJobInvoicingPlugIn(CYDAdHocServiceOrderJobInvoicing, defaultModel);
			AddJobInvoicingPlugIn(CYDReceiveAdviceJobInvoicing, defaultModel);
			AddJobInvoicingPlugIn(CYDReleaseAdviceJobInvoicing, defaultModel);
			AddJobInvoicingPlugIn(CYDTransportationUnitJobInvoicing, defaultModel);
			AddJobInvoicingPlugIn(MNRWorkOrderJobInvoicing, defaultModel);
		}

