		public SecurityCheckpoint GetInvoicingSecurityCheckPoint(SecurityCheckpoint parent, string name)
		{
			return parent != null ? GetInvoicingSecurityCheckPointCore(parent, parent.Code + name) ?? parent : null;
		}

		internal SecurityCheckpoint GetInvoicingSecurityCheckPointCore(SecurityCheckpoint parent, string name)
		{
			if (parent.Code == name)
			{
				return parent;
			}

			SecurityInstance.BuildJobInvoicingPluginCheckpoints(parent);
			if (parent.ChildCheckPoints == null) // Base Recursion Case
			{
				if (parent.Code == name)
				{
					return parent;
				}
			}
			else
			{
				foreach (SecurityCheckpoint checkPoint in parent.ChildCheckPoints)
				{
					SecurityCheckpoint securityCheckpointToReturn = GetInvoicingSecurityCheckPointCore(checkPoint, name);
					if (securityCheckpointToReturn != null)
					{
						return securityCheckpointToReturn;
					}
				}
			}

			return null;
		}

		static class JobInvoicingPluginModelConstants
		{
			public const string ShouldViewAllowInvoidingAmendmentsPastDays = nameof(ShouldViewAllowInvoidingAmendmentsPastDays);
			public const string AddPostLocalClient = nameof(AddPostLocalClient);
			public const string UseViewGlobalChargeDetailedConfiguration = nameof(UseViewGlobalChargeDetailedConfiguration);
			public const string ShouldAddMultiplePosting = nameof(ShouldAddMultiplePosting);
		}

		internal CheckpointBuilderModel GetJobInvoicingPlugInModel(bool shouldAddMultiplePosting = false, bool useViewGlobalChargeDetailedConfiguration = false, bool shouldViewAllowInvoicingAmendmentsPastDays = false, bool postLocalClient = true)
		{
			var model = new CheckpointBuilderModel();
			model.AddKey(JobInvoicingPluginModelConstants.ShouldAddMultiplePosting, shouldAddMultiplePosting);
			model.AddKey(JobInvoicingPluginModelConstants.UseViewGlobalChargeDetailedConfiguration, useViewGlobalChargeDetailedConfiguration);
			model.AddKey(JobInvoicingPluginModelConstants.ShouldViewAllowInvoidingAmendmentsPastDays, shouldViewAllowInvoicingAmendmentsPastDays);
			model.AddKey(JobInvoicingPluginModelConstants.AddPostLocalClient, postLocalClient);
			return model;
		}

		internal SecurityCheckpointBuilder MakeJobInvoicingPluginBuilder()
		{
			var parent = new SecurityCheckpointBuilder();
			parent.AddChild(new SecurityCheckpointBuilder(JobInvoicingPluginModelConstants.ShouldViewAllowInvoidingAmendmentsPastDays, AllowInvAmendmentsDays, ResString.GetMultilingualString("fbb694d9-576d-4e34-8b90-90d800b971cf", "Allow Invoicing Amendments Past Number of Days Set in the Registry")));

			AddInvoicing(parent, InvoicingDisplayText);
			AddProfitAndLoss(parent);
			AddViewProfitAndLossGlobalCharges(parent);
			AddInvoicePrinting(parent);
			AddCashAdvances(parent);
			AddCreditStatus(parent);
			AddMultiplePosting(parent);
			AddAllowViewEditBilling(parent);
			return parent;
		}

