		#region PopulateSecurityCheckpointsForStaffAssignments

		ReadOnlyDictionary<string, SecurityCheckpoint> PopulateSecurityCheckpointsForStaffAssignments(SecurityCheckpoint parent, IZSecurity securityInstance)
		{
			var lookup = new Dictionary<string, SecurityCheckpoint>();

			foreach (CodeDescriptionPair codeDescriptionPair in DataRegistry.Instance.OrgStaffMemberAssignmentRoles)
			{
				if (!string.IsNullOrWhiteSpace(codeDescriptionPair.Code) && !lookup.ContainsKey(codeDescriptionPair.Code))
				{
					lookup.Add(codeDescriptionPair.Code, new SecurityCheckpoint(string.Concat(parent.Code, ".", codeDescriptionPair.Code),
							(NoResString)codeDescriptionPair.Description,
							parent, securityInstance));
				}
			}

			return new ReadOnlyDictionary<string, SecurityCheckpoint>(lookup);
		}

