#if DEBUG
	public class SecurityCachingDisabler : Disposable
	{
		readonly SecurityCore instance;
		readonly bool initialCachingEnabled;

		public SecurityCachingDisabler(SecurityCore instance)
		{
			this.instance = instance;
			this.initialCachingEnabled = instance.CachingEnabled;
			instance.CachingEnabled = false;
		}

		protected override void Dispose(bool isDisposing)
		{
			if (isDisposing)
			{
				instance.CachingEnabled = initialCachingEnabled;
			}
		}
	}
#endif
